with flattened_attrs as (select id, host, log_ts, level, status_code, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, context['trace'] as trace from app_logs) select *, ntile(10) over (partition by level order by status_code, id) as status_code_bucket, lag(status_code, 2) over (partition by host order by retry_count, id) as prev_status_code from flattened_attrs
